def list_inboxes(limit=None, cursor=None, provider=None, status=None, sync_state=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_inboxes"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        # service-wide: 120/min, 50k/day
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    allowed_provider = {"agentmail", "gmail", "microsoft", "smtp_imap"}
    allowed_status = {"provisioning", "active", "paused", "disabled", "error"}
    allowed_sync = {"not_configured", "syncing", "up_to_date", "stalled", "error"}
    allowed_sort = {"created_at", "updated_at", "last_synced_at"}
    allowed_order = {"asc", "desc"}

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")

    if provider is not None and (not isinstance(provider, str) or provider not in allowed_provider):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "provider is invalid.", allowed=sorted(allowed_provider))

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(allowed_status))

    if sync_state is not None and (not isinstance(sync_state, str) or sync_state not in allowed_sync):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sync_state is invalid.", allowed=sorted(allowed_sync))

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.", allowed=sorted(allowed_sort))

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid.", allowed=sorted(allowed_order))

    # Cursor is opaque. Accept either:
    # - None
    # - base64url JSON {"o": <offset>}
    # - a raw inbox id (common client behaviour); treat as "start after this id" in the sorted list.
    offset = 0
    cursor_inbox_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        c = cursor.strip()
        if not c:
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        decoded_ok = False
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("o"), int) and obj.get("o") >= 0:
                offset = obj["o"]
                decoded_ok = True
        except Exception:
            decoded_ok = False
        if not decoded_ok:
            # treat as an id cursor (start after id)
            cursor_inbox_id = c

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []

    # Business rule: list_inboxes returns all inboxes with status in lifecycle values; ordered by created_at desc (default).
    rows = [r for r in inboxes if isinstance(r, dict) and r.get("status") in allowed_status]

    if provider is not None:
        rows = [r for r in rows if r.get("provider") == provider]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if sync_state is not None:
        rows = [r for r in rows if r.get("sync_state") == sync_state]

    def _sort_key(r):
        v = r.get(sort)
        dt = _parse_dt(v)
        # None sorts last for asc, first for desc (typical API behaviour)
        if dt is None:
            return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0, dt)

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)

    if cursor_inbox_id is not None:
        # find the position of this id in the current sorted set; start after it
        pos = None
        for i, r in enumerate(rows):
            if r.get("id") == cursor_inbox_id:
                pos = i
                break
        if pos is None:
            # opaque cursor: if it's not found, return empty page rather than hard error
            offset = total
        else:
            offset = pos + 1

    if offset < 0:
        offset = 0
    if offset > total:
        offset = total

    page = rows[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8")

    _audit("ok", None)
    return {
        "inboxes": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_inbox(inbox_id, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_inbox"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_window = now - datetime.timedelta(days=1)
        day_cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= day_window:
                day_cnt += 1
        if day_cnt >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _check_limits()
    if rl:
        _audit(429, error_code=rl["error"]["code"])
        return rl

    if not isinstance(inbox_id, str):
        e = _err("VALIDATION_ERROR", "inbox_id must be a string.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if not re.match(r"^am_inbox_[0-9A-Za-z]+$", inbox_id):
        e = _err("VALIDATION_ERROR", "inbox_id does not match expected format.")
        _audit(400, error_code=e["error"]["code"])
        return e

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []

    row = None
    for r in inboxes:
        if isinstance(r, dict) and r.get("id") == inbox_id:
            row = r
            break

    if row is None:
        e = _err("NOT_FOUND", "Inbox not found.")
        _audit(404, error_code=e["error"]["code"])
        return e

    # Ambient auth: if caller can invoke tool, it can access all local rows
    _audit(200)
    return row

def create_inbox(display_name, provider, email_address=None, metadata=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_inbox"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_window = now - datetime.timedelta(days=1)
        day_cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= day_window:
                day_cnt += 1
        if day_cnt >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _check_limits()
    if rl:
        _audit(429, error_code=rl["error"]["code"])
        return rl

    providers = {"agentmail", "gmail", "microsoft", "smtp_imap"}

    if not isinstance(display_name, str):
        e = _err("VALIDATION_ERROR", "display_name must be a string.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if len(display_name) < 1 or len(display_name) > 200:
        e = _err("VALIDATION_ERROR", "display_name length must be between 1 and 200.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if not isinstance(provider, str) or provider not in providers:
        e = _err("VALIDATION_ERROR", "provider must be one of the supported values.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if email_address is not None and not isinstance(email_address, str):
        e = _err("VALIDATION_ERROR", "email_address must be a string.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        e = _err("VALIDATION_ERROR", "metadata must be an object.")
        _audit(400, error_code=e["error"]["code"])
        return e

    # Email validation (RFC5322-like)
    if email_address is not None:
        email_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
        if not email_re.match(email_address):
            e = _err("VALIDATION_ERROR", "email_address must be a valid email format.")
            _audit(400, error_code=e["error"]["code"])
            return e

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []

    if email_address is not None:
        for r in inboxes:
            if isinstance(r, dict) and r.get("email_address") == email_address:
                e = _err("CONFLICT", "An inbox with this email_address already exists.")
                _audit(409, error_code=e["error"]["code"])
                return e

    # Provider/email_address acceptability (light policy): provider-backed inboxes require email_address except agentmail
    if provider != "agentmail" and not email_address:
        e = _err("VALIDATION_ERROR", "email_address is required for this provider.")
        _audit(400, error_code=e["error"]["code"])
        return e

    now = _now_iso()
    new_id = "am_inbox_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")

    row = {
        "id": new_id,
        "display_name": display_name,
        "email_address": email_address if email_address is not None else (new_id + "@agentmail.local"),
        "provider": provider,
        "status": "provisioning",
        "sync_state": "not_configured",
        "last_synced_at": None,
        "metadata": metadata,
        "created_at": now,
        "updated_at": now
    }

    inboxes.append(row)
    _save("inboxes.json", inboxes)

    _audit(201)
    return row

def list_threads(inbox_id, limit=None, cursor=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_threads"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        day_window = now - datetime.timedelta(days=1)
        day_cnt = 0
        for r in logs:
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= day_window:
                day_cnt += 1
        if day_cnt >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _check_limits()
    if rl:
        _audit(429, error_code=rl["error"]["code"])
        return rl

    if not isinstance(inbox_id, str) or not re.match(r"^am_inbox_[0-9A-Za-z]+$", inbox_id):
        e = _err("VALIDATION_ERROR", "inbox_id does not match expected format.")
        _audit(400, error_code=e["error"]["code"])
        return e

    if limit is not None and not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if limit is not None and limit <= 0:
        e = _err("VALIDATION_ERROR", "limit must be a positive integer.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.")
        _audit(400, error_code=e["error"]["code"])
        return e

    statuses = {"active", "archived", "deleted"}
    sort_fields = {"last_message_at", "created_at", "updated_at"}
    orders = {"asc", "desc"}

    if status is not None and status not in statuses:
        e = _err("VALIDATION_ERROR", "status must be one of the allowed values.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if sort is not None and sort not in sort_fields:
        e = _err("VALIDATION_ERROR", "sort must be one of the allowed values.")
        _audit(400, error_code=e["error"]["code"])
        return e
    if order is not None and order not in orders:
        e = _err("VALIDATION_ERROR", "order must be one of the allowed values.")
        _audit(400, error_code=e["error"]["code"])
        return e

    if sort is None:
        sort = "last_message_at"
    if order is None:
        order = "desc"
    page_limit = limit if limit is not None else 50
    if page_limit > 200:
        page_limit = 200

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or "o" not in payload or payload.get("inbox_id") != inbox_id:
                raise ValueError("bad cursor")
            start = payload["o"]
            if not isinstance(start, int) or start < 0:
                raise ValueError("bad cursor")
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed.")
            _audit(400, error_code=e["error"]["code"])
            return e

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_exists = any(isinstance(r, dict) and r.get("id") == inbox_id for r in inboxes)
    if not inbox_exists:
        e = _err("NOT_FOUND", "Inbox not found.")
        _audit(404, error_code=e["error"]["code"])
        return e

    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []

    rows = [r for r in threads if isinstance(r, dict) and r.get("inbox_id") == inbox_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _sort_key(r):
        dt = _parse_dt(r.get(sort))
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if order == "asc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        return dt

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[start:start + page_limit]
    next_cursor = None
    if start + page_limit < total:
        payload = {"v": 1, "o": start + page_limit, "inbox_id": inbox_id}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    resp = {
        "object": "list",
        "data": page,
        "limit": page_limit,
        "total": total,
        "has_more": (next_cursor is not None),
        "next_cursor": next_cursor
    }
    _audit(200)
    return resp

def list_all_threads(limit=None, cursor=None, status=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_all_threads"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    allowed_status = {"active", "archived", "deleted"}
    allowed_sort = {"last_message_at", "created_at", "updated_at"}
    allowed_order = {"asc", "desc"}

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(allowed_status))

    if sort is None:
        sort = "last_message_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.", allowed=sorted(allowed_sort))

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid.", allowed=sorted(allowed_order))

    offset = 0
    cursor_thread_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string")
        c = cursor.strip()
        if not c:
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid")
        decoded_ok = False
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("o"), int) and obj.get("o") >= 0:
                offset = obj["o"]
                decoded_ok = True
        except Exception:
            decoded_ok = False
        if not decoded_ok:
            # accept raw id cursor (even if it's an inbox id due to client bug); treat as "start after matching id if present"
            cursor_thread_id = c

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_ids = {i.get("id") for i in inboxes if isinstance(i, dict) and isinstance(i.get("id"), str)}
    if not inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible inbox context found")

    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []

    rows = [t for t in threads if isinstance(t, dict) and t.get("inbox_id") in inbox_ids]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]

    def _sort_key(r):
        v = r.get(sort)
        dt = _parse_dt(v)
        if dt is None:
            return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0, dt)

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)
    total = len(rows)

    if cursor_thread_id is not None:
        pos = None
        for i, r in enumerate(rows):
            if r.get("id") == cursor_thread_id:
                pos = i
                break
        if pos is None:
            offset = total
        else:
            offset = pos + 1

    if offset < 0:
        offset = 0
    if offset > total:
        offset = total

    page = rows[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8")

    _audit("ok", None)
    return {
        "threads": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_thread(thread_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log_call(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"am_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_thread",
            "timestamp": now,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        rl = _load("rate_limits.json")
        if not isinstance(rl, dict):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = rl.get("per_minute")
        if isinstance(per_min, int) and per_min > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        per_day = rl.get("per_day")
        if isinstance(per_day, int) and per_day > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = now - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= per_day:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    if not isinstance(thread_id, str) or not re.match(r"^am_th_[0-9A-Za-z]+$", thread_id):
        e = _err("VALIDATION_ERROR", "thread_id must match pattern ^am_th_[0-9A-Za-z]+$")
        _log_call(400, e["error"]["code"])
        return e

    limerr = _enforce_limits()
    if limerr:
        _log_call(429 if limerr["error"]["code"] == "RATE_LIMIT" else 403, limerr["error"]["code"])
        return limerr

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    if len(inboxes) == 0:
        e = _err("UNAUTHORIZED", "No accessible inboxes for this account")
        _log_call(401, e["error"]["code"])
        return e
    inbox_ids = {i.get("id") for i in inboxes if isinstance(i, dict) and i.get("id")}

    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []
    th = None
    for t in threads:
        if isinstance(t, dict) and t.get("id") == thread_id:
            th = t
            break
    if th is None:
        e = _err("NOT_FOUND", "Thread not found")
        _log_call(404, e["error"]["code"])
        return e

    if th.get("inbox_id") not in inbox_ids:
        e = _err("UNAUTHORIZED", "Not authorized to access this thread")
        _log_call(403, e["error"]["code"])
        return e

    # Optionally include derived aggregates from messages (message_count, last_message_at)
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []
    cnt = 0
    last_dt = None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("thread_id") != thread_id:
            continue
        if m.get("status") == "deleted":
            continue
        cnt += 1
        dt = _parse_dt(m.get("sent_at")) or _parse_dt(m.get("created_at"))
        if dt and (last_dt is None or dt > last_dt):
            last_dt = dt

    # Return a copy with derived fields (do not persist)
    out = dict(th)
    out["message_count"] = cnt if isinstance(cnt, int) else out.get("message_count")
    out["last_message_at"] = (last_dt.isoformat() if last_dt else out.get("last_message_at"))

    _log_call(200, None)
    return {"object": "thread", "data": out}

def list_messages(inbox_id, thread_id=None, limit=None, cursor=None, direction=None, status=None, is_read=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _cursor_decode(c):
        if c is None:
            return None
        if not isinstance(c, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or "o" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        o = obj.get("o")
        if not isinstance(o, int) or o < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        return o

    def _cursor_encode(offset):
        payload = json.dumps({"o": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8")

    def _log_call(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"am_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "list_messages",
            "timestamp": now,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
        })
        _save("request_logs.json", logs)

    def _enforce_limits():
        rl = _load("rate_limits.json")
        if not isinstance(rl, dict):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = rl.get("per_minute")
        if isinstance(per_min, int) and per_min > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = now - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        per_day = rl.get("per_day")
        if isinstance(per_day, int) and per_day > 0:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            cutoff = now - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt >= per_day:
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    if not isinstance(inbox_id, str) or not re.match(r"^am_inbox_[0-9A-Za-z]+$", inbox_id):
        e = _err("VALIDATION_ERROR", "inbox_id must match pattern ^am_inbox_[0-9A-Za-z]+$")
        _log_call(400, e["error"]["code"])
        return e

    if thread_id is not None:
        if not isinstance(thread_id, str) or not re.match(r"^am_th_[0-9A-Za-z]+$", thread_id):
            e = _err("VALIDATION_ERROR", "thread_id must match pattern ^am_th_[0-9A-Za-z]+$")
            _log_call(400, e["error"]["code"])
            return e

    if direction is not None:
        if not isinstance(direction, str) or direction not in ("inbound", "outbound"):
            e = _err("VALIDATION_ERROR", "direction must be one of: inbound, outbound")
            _log_call(400, e["error"]["code"])
            return e

    if status is not None:
        if not isinstance(status, str) or status not in ("received", "queued", "sending", "sent", "failed", "deleted"):
            e = _err("VALIDATION_ERROR", "status must be one of: received, queued, sending, sent, failed, deleted")
            _log_call(400, e["error"]["code"])
            return e

    if is_read is not None and not isinstance(is_read, bool):
        e = _err("VALIDATION_ERROR", "is_read must be a boolean")
        _log_call(400, e["error"]["code"])
        return e

    limit_default = 50
    limit_max = 200
    if limit is None:
        limit = limit_default
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer")
        _log_call(400, e["error"]["code"])
        return e
    if limit < 1 or limit > limit_max:
        e = _err("VALIDATION_ERROR", f"limit must be between 1 and {limit_max}")
        _log_call(400, e["error"]["code"])
        return e

    if sort is None:
        sort = "sent_at"
    if not isinstance(sort, str) or sort not in ("sent_at", "created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "sort must be one of: sent_at, created_at, updated_at")
        _log_call(400, e["error"]["code"])
        return e

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc")
        _log_call(400, e["error"]["code"])
        return e

    off = 0
    dec = _cursor_decode(cursor)
    if isinstance(dec, dict) and "error" in dec:
        _log_call(400, dec["error"]["code"])
        return dec
    if isinstance(dec, int):
        off = dec

    limerr = _enforce_limits()
    if limerr:
        _log_call(429 if limerr["error"]["code"] == "RATE_LIMIT" else 403, limerr["error"]["code"])
        return limerr

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox = None
    for i in inboxes:
        if isinstance(i, dict) and i.get("id") == inbox_id:
            inbox = i
            break
    if inbox is None:
        e = _err("NOT_FOUND", "Inbox not found")
        _log_call(404, e["error"]["code"])
        return e

    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []
    if thread_id is not None:
        th = None
        for t in threads:
            if isinstance(t, dict) and t.get("id") == thread_id:
                th = t
                break
        if th is None:
            e = _err("NOT_FOUND", "Thread not found")
            _log_call(404, e["error"]["code"])
            return e
        if th.get("inbox_id") != inbox_id:
            e = _err("UNAUTHORIZED", "Not authorized to access this thread in the requested inbox")
            _log_call(403, e["error"]["code"])
            return e

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    # default: exclude deleted unless explicitly requested
    include_deleted = (status == "deleted")

    out = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("inbox_id") != inbox_id:
            continue
        if thread_id is not None and m.get("thread_id") != thread_id:
            continue
        if direction is not None and m.get("direction") != direction:
            continue
        if status is not None and m.get("status") != status:
            continue
        if not include_deleted and m.get("status") == "deleted":
            continue
        if is_read is not None and m.get("is_read") != is_read:
            continue
        out.append(m)

    def _sort_key(m):
        v = _parse_dt(m.get(sort))
        if v is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if order == "asc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        return v

    reverse = (order == "desc")
    def _combined_key(m):
        return (_sort_key(m), str(m.get("id") or ""))

    out.sort(key=_combined_key, reverse=reverse)

    total = len(out)
    page = out[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _cursor_encode(next_off) if has_more else None

    _log_call(200, None)
    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_message(message_id, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_message"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    # Relax validation: real clients sometimes pass provider Message-Id (<...@...>).
    # Accept any non-empty string; attempt to resolve by internal id or provider_message_id.
    if not isinstance(message_id, str) or not message_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string.")

    mid = message_id.strip()

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_ids = {i.get("id") for i in inboxes if isinstance(i, dict) and isinstance(i.get("id"), str)}
    if not inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible inbox context found")

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    msg = None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("id") == mid or (m.get("provider_message_id") is not None and m.get("provider_message_id") == mid):
            msg = m
            break

    if msg is None:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.", message_id=message_id)

    if msg.get("inbox_id") not in inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this message.")

    # Optional join thread
    thread = None
    tid = msg.get("thread_id")
    if tid is not None:
        threads = _load("threads.json")
        if isinstance(threads, list):
            for t in threads:
                if isinstance(t, dict) and t.get("id") == tid:
                    thread = t
                    break

    _audit("ok", None)
    out = {"message": msg}
    if thread is not None:
        out["thread"] = thread
    return out

def send_message(inbox_id, to_emails, thread_id=None, from_email=None, cc_emails=None, bcc_emails=None, reply_to_emails=None, subject=None, body_text=None, body_html=None, headers=None, labels=None, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit():
        # Best-effort: only enforced if request_logs.json exists and is list.
        try:
            p = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(p):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.now(datetime.timezone.utc)
            window_s = 60
            limit = 120
            cnt = 0
            for r in reversed(logs[-2000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if (now - ts).total_seconds() <= window_s:
                    cnt += 1
                else:
                    break
            if cnt >= limit:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            return None
        except Exception:
            return None

    rl = _check_rate_limit()
    if rl:
        _audit("send_message", "error", rl["error"]["message"])
        return rl

    # Validate inputs
    if not isinstance(inbox_id, str) or not re.match(r"^am_inbox_[0-9A-Z]+$", inbox_id):
        e = _err("VALIDATION_ERROR", "inbox_id is invalid.", field="inbox_id")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if thread_id is not None and (not isinstance(thread_id, str) or not re.match(r"^am_th_[0-9A-Z]+$", thread_id)):
        e = _err("VALIDATION_ERROR", "thread_id is invalid.", field="thread_id")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if not isinstance(to_emails, list) or any(not isinstance(x, str) for x in to_emails):
        e = _err("VALIDATION_ERROR", "to_emails must be an array of strings.", field="to_emails")
        _audit("send_message", "error", e["error"]["message"])
        return e

    def _val_email_list(name, v, allow_none=True, max_len=100):
        if v is None and allow_none:
            return []
        if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings.", field=name)
        if len(v) > max_len:
            return _err("VALIDATION_ERROR", f"{name} must have length <= {max_len}.", field=name)
        return v

    ccv = _val_email_list("cc_emails", cc_emails)
    if isinstance(ccv, dict) and "error" in ccv:
        _audit("send_message", "error", ccv["error"]["message"])
        return ccv
    bccv = _val_email_list("bcc_emails", bcc_emails)
    if isinstance(bccv, dict) and "error" in bccv:
        _audit("send_message", "error", bccv["error"]["message"])
        return bccv
    rtv = _val_email_list("reply_to_emails", reply_to_emails)
    if isinstance(rtv, dict) and "error" in rtv:
        _audit("send_message", "error", rtv["error"]["message"])
        return rtv

    if len(to_emails) == 0 and len(ccv) == 0 and len(bccv) == 0:
        e = _err("VALIDATION_ERROR", "At least one recipient across to_emails/cc_emails/bcc_emails is required.", field="to_emails")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if from_email is not None and not isinstance(from_email, str):
        e = _err("VALIDATION_ERROR", "from_email must be a string.", field="from_email")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if subject is not None and not isinstance(subject, str):
        e = _err("VALIDATION_ERROR", "subject must be a string.", field="subject")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if body_text is not None and not isinstance(body_text, str):
        e = _err("VALIDATION_ERROR", "body_text must be a string.", field="body_text")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if body_html is not None and not isinstance(body_html, str):
        e = _err("VALIDATION_ERROR", "body_html must be a string.", field="body_html")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if (body_text is None or body_text == "") and (body_html is None or body_html == ""):
        e = _err("VALIDATION_ERROR", "At least one of body_text or body_html is required.", field="body_text")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if headers is not None and not isinstance(headers, dict):
        e = _err("VALIDATION_ERROR", "headers must be an object.", field="headers")
        _audit("send_message", "error", e["error"]["message"])
        return e

    if labels is None:
        labels_v = []
    else:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            e = _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")
            _audit("send_message", "error", e["error"]["message"])
            return e
        labels_v = labels

    if len(ccv) > 100 or len(bccv) > 100 or len(rtv) > 100 or len(to_emails) > 100:
        e = _err("VALIDATION_ERROR", "Recipient arrays must have length <= 100.", field="to_emails")
        _audit("send_message", "error", e["error"]["message"])
        return e

    # Load store
    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    inbox = next((r for r in inboxes if r.get("id") == inbox_id), None)
    if not inbox:
        e = _err("NOT_FOUND", "Inbox not found.", inbox_id=inbox_id)
        _audit("send_message", "error", e["error"]["message"])
        return e

    # Enforce thread integrity if provided
    if thread_id is not None:
        th = next((t for t in threads if t.get("id") == thread_id), None)
        if not th:
            e = _err("NOT_FOUND", "Thread not found.", thread_id=thread_id)
            _audit("send_message", "error", e["error"]["message"])
            return e
        if th.get("inbox_id") != inbox_id:
            e = _err("CONFLICT", "thread_id does not belong to the specified inbox.", thread_id=thread_id, inbox_id=inbox_id)
            _audit("send_message", "error", e["error"]["message"])
            return e
        if th.get("status") == "deleted":
            e = _err("CONFLICT", "Cannot send message into a deleted thread.", thread_id=thread_id)
            _audit("send_message", "error", e["error"]["message"])
            return e

    # Default from_email to inbox email if not provided
    if from_email is None:
        from_email = inbox.get("email_address")
    if not isinstance(from_email, str) or from_email.strip() == "":
        e = _err("VALIDATION_ERROR", "from_email is required and must be a non-empty string.", field="from_email")
        _audit("send_message", "error", e["error"]["message"])
        return e

    # Create message row
    def _new_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")

    now = _now()
    msg_id = _new_id("am_msg_")

    msg = {
        "id": msg_id,
        "inbox_id": inbox_id,
        "thread_id": thread_id,
        "provider_message_id": None,
        "direction": "outbound",
        "from_email": from_email,
        "to_emails": list(to_emails),
        "cc_emails": list(ccv),
        "bcc_emails": list(bccv),
        "reply_to_emails": list(rtv),
        "subject": subject,
        "body_text": body_text,
        "body_html": body_html,
        "headers": headers if isinstance(headers, dict) else {},
        "labels": list(labels_v),
        "is_read": True,
        "sent_at": None,
        "status": "queued",
        "in_reply_to_message_id": None,
        "created_at": now,
        "updated_at": now,
    }

    # Enforce constraints relevant to outbound creation
    if msg["status"] not in ("queued", "sending", "sent", "failed", "deleted"):
        e = _err("VALIDATION_ERROR", "Invalid outbound message status.")
        _audit("send_message", "error", e["error"]["message"])
        return e

    # Persist
    messages.append(msg)
    _save("messages.json", messages)

    # Update thread aggregates when thread_id provided
    if thread_id is not None:
        for t in threads:
            if t.get("id") == thread_id:
                mc = t.get("message_count")
                if not isinstance(mc, int) or mc < 0:
                    mc = 0
                t["message_count"] = mc + 1
                # last_message_at can be null; set to now for outbound queued as "last activity"
                t["last_message_at"] = now
                t["updated_at"] = now
                break
        _save("threads.json", threads)

    _audit("send_message", "ok")
    return {"message": msg}

def reply_to_message(inbox_id, message_id, from_email=None, to_emails=None, cc_emails=None, bcc_emails=None, subject=None, body_text=None, body_html=None, headers=None, labels=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    t0 = time.time()
    endpoint = "reply_to_message"

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    if not isinstance(inbox_id, str) or not inbox_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inbox_id must be a non-empty string.")
    if not isinstance(message_id, str) or not message_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string.")

    # Relax patterns: datastore + real calls may use mixed-case ids or provider ids (<...@...>)
    # We still sanity-check inbox_id resembles am_inbox_...
    if not re.match(r"^am_inbox_[0-9A-Za-z]+$", inbox_id.strip()):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inbox_id format is invalid.")

    def _validate_str_array(name, arr, max_len=100):
        if arr is None:
            return None
        if not isinstance(arr, list):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings.")
        if len(arr) > max_len:
            return _err("VALIDATION_ERROR", f"{name} length must be <= {max_len}.")
        for x in arr:
            if not isinstance(x, str):
                return _err("VALIDATION_ERROR", f"{name} must contain only strings.")
        return None

    e = _validate_str_array("to_emails", to_emails)
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    e = _validate_str_array("cc_emails", cc_emails)
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    e = _validate_str_array("bcc_emails", bcc_emails)
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e
    e = _validate_str_array("labels", labels, max_len=200)
    if e:
        _audit("error", "VALIDATION_ERROR")
        return e

    if headers is None:
        headers = {}
    if not isinstance(headers, dict):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "headers must be an object.")

    if from_email is not None and not isinstance(from_email, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from_email must be a string.")
    if subject is not None and not isinstance(subject, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subject must be a string.")
    if body_text is not None and not isinstance(body_text, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body_text must be a string.")
    if body_html is not None and not isinstance(body_html, str):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body_html must be a string.")

    if (body_text is None or body_text == "") and (body_html is None or body_html == ""):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of body_text or body_html must be provided.")

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox = None
    for i in inboxes:
        if isinstance(i, dict) and i.get("id") == inbox_id:
            inbox = i
            break
    if inbox is None:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Inbox not found.", inbox_id=inbox_id)

    if inbox.get("status") == "disabled":
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Inbox is disabled.", inbox_id=inbox_id)

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    target = None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if (m.get("id") == message_id) or (m.get("provider_message_id") is not None and m.get("provider_message_id") == message_id):
            target = m
            break
    if target is None:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Original message not found.", message_id=message_id)

    if target.get("inbox_id") != inbox_id:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Reply target does not belong to the specified inbox.", inbox_id=inbox_id)

    # Resolve reply thread_id: inherit from target; if missing, try to find or create a thread deterministically.
    thread_id = target.get("thread_id")
    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []

    if thread_id is not None:
        # Ensure thread exists and belongs to inbox
        th = None
        for t in threads:
            if isinstance(t, dict) and t.get("id") == thread_id:
                th = t
                break
        if th is None or th.get("inbox_id") != inbox_id:
            thread_id = None  # fall back to creating/linking a new thread

    if thread_id is None:
        # Attempt link by provider_thread_id if available on target thread/provider headers; else create a new thread.
        # We keep it simple: create a thread that includes from/to participants.
        participants = []
        fe = target.get("from_email")
        if isinstance(fe, str) and fe:
            participants.append(fe)
        for arr_name in ("to_emails", "cc_emails", "bcc_emails"):
            arr = target.get(arr_name)
            if isinstance(arr, list):
                for x in arr:
                    if isinstance(x, str) and x:
                        participants.append(x)
        # de-dup preserving order
        seen = set()
        participants2 = []
        for p in participants:
            if p not in seen:
                seen.add(p)
                participants2.append(p)
        now = _now_iso()
        new_thread_id = "am_th_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        thread_row = {
            "id": new_thread_id,
            "inbox_id": inbox_id,
            "provider_thread_id": None,
            "subject": target.get("subject"),
            "participants": participants2,
            "message_count": 0,
            "last_message_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        threads.append(thread_row)
        _save("threads.json", threads)
        thread_id = new_thread_id

    # Build recipients. If to_emails not provided, default to replying to original sender.
    if to_emails is None:
        to_emails = []
        if isinstance(target.get("from_email"), str) and target.get("from_email"):
            to_emails = [target.get("from_email")]

    if cc_emails is None:
        cc_emails = []
    if bcc_emails is None:
        bcc_emails = []

    if not isinstance(to_emails, list) or not isinstance(cc_emails, list) or not isinstance(bcc_emails, list):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Recipient fields must be arrays.")

    if (len(to_emails) + len(cc_emails) + len(bcc_emails)) < 1:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one recipient across to_emails/cc_emails/bcc_emails is required.")

    # from_email default: inbox email_address
    if from_email is None:
        from_email = inbox.get("email_address")

    # subject default: "Re: <original subject>" if not already
    if subject is None:
        orig_subj = target.get("subject") if isinstance(target.get("subject"), str) else ""
        subject = orig_subj
        if isinstance(subject, str) and subject and not subject.lower().startswith("re:"):
            subject = "Re: " + subject
        elif not subject:
            subject = "Re:"

    now = _now_iso()
    # id generation
    new_msg_id = "am_msg_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    # enforce unique (inbox_id, provider_message_id) when provider_message_id not null; we are creating outbound => provider_message_id None
    msg_row = {
        "id": new_msg_id,
        "inbox_id": inbox_id,
        "thread_id": thread_id,
        "provider_message_id": None,
        "direction": "outbound",
        "from_email": from_email,
        "to_emails": to_emails,
        "cc_emails": cc_emails,
        "bcc_emails": bcc_emails,
        "reply_to_emails": [],
        "subject": subject,
        "body_text": body_text,
        "body_html": body_html,
        "headers": headers,
        "labels": labels if isinstance(labels, list) else [],
        "is_read": True,
        "sent_at": None,
        "status": "queued",
        "in_reply_to_message_id": target.get("id"),
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: at least one of body_text/body_html non-null for outbound in status != failed
    if (msg_row["body_text"] is None or msg_row["body_text"] == "") and (msg_row["body_html"] is None or msg_row["body_html"] == ""):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Outbound messages require body_text or body_html.")

    # Constraint: recipient array lengths <= 100
    for nm in ("to_emails", "cc_emails", "bcc_emails", "reply_to_emails"):
        arr = msg_row.get(nm)
        if isinstance(arr, list) and len(arr) > 100:
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{nm} length must be <= 100.")

    messages.append(msg_row)
    _save("messages.json", messages)

    # Update thread aggregates: message_count, last_message_at
    # compute based on all non-deleted messages in this thread
    msgs_for_thread = [m for m in messages if isinstance(m, dict) and m.get("thread_id") == thread_id and m.get("inbox_id") == inbox_id and m.get("status") != "deleted"]
    last_ts = None
    for m in msgs_for_thread:
        ts = _parse_dt(m.get("sent_at")) or _parse_dt(m.get("created_at"))
        if ts and (last_ts is None or ts > last_ts):
            last_ts = ts
    for i, t in enumerate(threads):
        if isinstance(t, dict) and t.get("id") == thread_id:
            threads[i] = dict(t)
            threads[i]["message_count"] = len(msgs_for_thread)
            threads[i]["last_message_at"] = (last_ts.isoformat() if last_ts else None)
            threads[i]["updated_at"] = now
            break
    _save("threads.json", threads)

    _audit("ok", None)
    return {"message": msg_row}

def update_message(message_id, is_read=None, labels=None, status=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_message"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return False, _err("RATE_LIMIT", "Rate limit exceeded (per-minute).")
        if c_day >= per_day:
            return False, _err("QUOTA_EXCEEDED", "Quota exceeded (per-day).")
        return True, None

    ok, limit_err = _rate_limit_check()
    if not ok:
        _audit(429, limit_err["error"]["code"])
        return limit_err

    # Validate message_id: relax overly-strict pattern to allow provider ids too.
    # The vendor schema shows am_msg_..., but real calls may use provider Message-Id strings.
    if not isinstance(message_id, str) or not message_id.strip():
        e = _err("VALIDATION_ERROR", "message_id must be a non-empty string.", message_id=message_id)
        _audit(400, e["error"]["code"])
        return e
    mid = message_id.strip()
    # Accept either internal id or a provider message-id-like string (e.g., <...@...>)
    if not re.match(r"^am_msg_[0-9A-Za-z]+$", mid) and not re.match(r"^<[^<>@\s]+@[^<>@\s]+>$", mid):
        e = _err("VALIDATION_ERROR", "message_id is invalid.", message_id=message_id)
        _audit(400, e["error"]["code"])
        return e

    if is_read is None and labels is None and status is None:
        e = _err("VALIDATION_ERROR", "No writable fields provided.")
        _audit(400, e["error"]["code"])
        return e

    if is_read is not None and not isinstance(is_read, bool):
        e = _err("VALIDATION_ERROR", "is_read must be a boolean.", is_read=is_read)
        _audit(400, e["error"]["code"])
        return e

    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            e = _err("VALIDATION_ERROR", "labels must be an array of strings.", labels=labels)
            _audit(400, e["error"]["code"])
            return e
        if len(labels) > 1000:
            e = _err("VALIDATION_ERROR", "labels is too large.", max=1000)
            _audit(400, e["error"]["code"])
            return e

    allowed_status = {"received", "queued", "sending", "sent", "failed", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "Unknown status.", status=status)
            _audit(400, e["error"]["code"])
            return e

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    # Find by internal id first; if not found, allow lookup by provider_message_id or headers.Message-Id
    msg = None
    idx = None
    for i, m in enumerate(messages):
        if isinstance(m, dict) and m.get("id") == mid:
            msg, idx = m, i
            break
    if msg is None:
        for i, m in enumerate(messages):
            if not isinstance(m, dict):
                continue
            if m.get("provider_message_id") == mid:
                msg, idx = m, i
                break
            h = m.get("headers")
            if isinstance(h, dict) and h.get("Message-Id") == mid:
                msg, idx = m, i
                break

    if msg is None:
        e = _err("NOT_FOUND", "Message not found.", message_id=message_id)
        _audit(404, e["error"]["code"])
        return e

    # Enforce mutability: only is_read and labels are mutable; status transitions must follow lifecycle rules.
    # Some clients pass status redundantly (e.g., status='received' on inbound). Treat no-op as idempotent.
    transitions = {
        "received": {"deleted"},
        "queued": {"sending", "failed", "deleted"},
        "sending": {"sent", "failed", "deleted"},
        "sent": {"deleted"},
        "failed": {"queued", "deleted"},
        "deleted": set(),
    }

    # Apply changes with validation against message constraints.
    updated = dict(msg)
    now_iso = _now_iso()

    if is_read is not None:
        updated["is_read"] = is_read

    if labels is not None:
        updated["labels"] = labels

    if status is not None:
        cur = updated.get("status")
        if cur is None or cur not in transitions:
            e = _err("VALIDATION_ERROR", "Stored message has invalid status.", stored_status=cur)
            _audit(400, e["error"]["code"])
            return e
        if status != cur:
            if status not in transitions.get(cur, set()):
                e = _err("INVALID_TRANSITION", "Status transition is not permitted.", from_status=cur, to_status=status)
                _audit(409, e["error"]["code"])
                return e
            # Direction constraints
            direction = updated.get("direction")
            if direction == "inbound" and status not in ("received", "deleted"):
                e = _err("VALIDATION_ERROR", "Inbound messages may only be 'received' or 'deleted'.", direction=direction, status=status)
                _audit(400, e["error"]["code"])
                return e
            if direction == "outbound" and status not in ("queued", "sending", "sent", "failed", "deleted"):
                e = _err("VALIDATION_ERROR", "Outbound messages must have an outbound-allowed status.", direction=direction, status=status)
                _audit(400, e["error"]["code"])
                return e
            # sent_at required when status in ('received','sent')
            if status in ("received", "sent") and not updated.get("sent_at"):
                # If moving to 'received' or 'sent' and sent_at missing, set to now (realistic server behavior)
                updated["sent_at"] = now_iso
            updated["status"] = status

    updated["updated_at"] = now_iso

    # Thread/inbox FK consistency (defensive; shouldn't break)
    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_id = updated.get("inbox_id")
    if not inbox_id or not any(isinstance(x, dict) and x.get("id") == inbox_id for x in inboxes):
        e = _err("NOT_FOUND", "Owning inbox not found for message.", inbox_id=inbox_id)
        _audit(404, e["error"]["code"])
        return e

    thread_id = updated.get("thread_id")
    if thread_id is not None:
        threads = _load("threads.json")
        if not isinstance(threads, list):
            threads = []
        th = next((t for t in threads if isinstance(t, dict) and t.get("id") == thread_id), None)
        if th is None:
            # FK on delete set null, so allow nulling
            updated["thread_id"] = None
        else:
            if th.get("inbox_id") != inbox_id:
                e = _err("VALIDATION_ERROR", "thread_id must belong to the same inbox as the message.", thread_id=thread_id, inbox_id=inbox_id)
                _audit(400, e["error"]["code"])
                return e

    messages[idx] = updated
    _save("messages.json", messages)
    _audit(200, None)
    return {"message": updated}

def list_drafts(inbox_id, thread_id=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status_s, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_rate_limit():
        try:
            p = os.path.join(_DB, "request_logs.json")
            if not os.path.exists(p):
                return None
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            now = datetime.datetime.now(datetime.timezone.utc)
            window_s = 60
            limit_calls = 240
            cnt = 0
            for r in reversed(logs[-4000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if (now - ts).total_seconds() <= window_s:
                    cnt += 1
                else:
                    break
            if cnt >= limit_calls:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
            return None
        except Exception:
            return None

    rl = _check_rate_limit()
    if rl:
        _audit("list_drafts", "error", rl["error"]["message"])
        return rl

    # Validate
    if not isinstance(inbox_id, str) or not re.match(r"^am_inbox_[0-9A-Z]+$", inbox_id):
        e = _err("VALIDATION_ERROR", "inbox_id is invalid.", field="inbox_id")
        _audit("list_drafts", "error", e["error"]["message"])
        return e

    if thread_id is not None and (not isinstance(thread_id, str) or not re.match(r"^am_th_[0-9A-Z]+$", thread_id)):
        e = _err("VALIDATION_ERROR", "thread_id is invalid.", field="thread_id")
        _audit("list_drafts", "error", e["error"]["message"])
        return e

    allowed_status = {"draft", "sending", "sent", "discarded", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(allowed_status))
        _audit("list_drafts", "error", e["error"]["message"])
        return e

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            e = _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            _audit("list_drafts", "error", e["error"]["message"])
            return e
        if limit < 1 or limit > 200:
            e = _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
            _audit("list_drafts", "error", e["error"]["message"])
            return e
        limit_v = limit

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        _audit("list_drafts", "error", e["error"]["message"])
        return e

    if sort_by is None:
        sort_by_v = "created_at"
    else:
        if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at"):
            e = _err("VALIDATION_ERROR", "sort_by is invalid.", field="sort_by")
            _audit("list_drafts", "error", e["error"]["message"])
            return e
        sort_by_v = sort_by

    if sort_order is None:
        sort_order_v = "desc"
    else:
        if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
            e = _err("VALIDATION_ERROR", "sort_order is invalid.", field="sort_order")
            _audit("list_drafts", "error", e["error"]["message"])
            return e
        sort_order_v = sort_order

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox = next((r for r in inboxes if r.get("id") == inbox_id), None)
    if not inbox:
        e = _err("NOT_FOUND", "Inbox not found.", inbox_id=inbox_id)
        _audit("list_drafts", "error", e["error"]["message"])
        return e

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []

    # Filter by inbox
    rows = [d for d in drafts if d.get("inbox_id") == inbox_id]

    # Optional filters
    if thread_id is not None:
        rows = [d for d in rows if d.get("thread_id") == thread_id]

    if status is not None:
        rows = [d for d in rows if d.get("status") == status]
    else:
        # Default per business rules: status in ('draft','sending','error')
        rows = [d for d in rows if d.get("status") in ("draft", "sending", "error")]

    # Sort (stable) using dt then id as tiebreaker
    reverse = (sort_order_v == "desc")

    def _key(d):
        dt = _parse_dt(d.get(sort_by_v))
        # Put missing dates last for asc, first for desc
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        return (dt, d.get("id") or "")

    rows.sort(key=_key, reverse=reverse)

    # Cursor: base64 of "offset:<n>"
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"==").decode("utf-8", "strict")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                e = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
                _audit("list_drafts", "error", e["error"]["message"])
                return e
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _audit("list_drafts", "error", e["error"]["message"])
            return e

    total = len(rows)
    page = rows[offset: offset + limit_v]
    next_cursor = None
    if offset + limit_v < total:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset + limit_v}".encode("utf-8")).decode("ascii").rstrip("=")

    _audit("list_drafts", "ok")
    return {
        "drafts": page,
        "pagination": {
            "total": total,
            "limit": limit_v,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
        },
        "sort": {"sort_by": sort_by_v, "sort_order": sort_order_v},
    }

def list_all_drafts(status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_all_drafts"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    allowed_status = {"draft", "sending", "sent", "discarded", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(allowed_status))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1–200).")

    allowed_sort_by = {"created_at", "updated_at"}
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=sorted(allowed_sort_by))

    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=sorted(allowed_sort_order))

    offset = 0
    cursor_draft_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")
        c = cursor.strip()
        if not c:
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        decoded_ok = False
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("o"), int) and obj.get("o") >= 0:
                offset = obj["o"]
                decoded_ok = True
        except Exception:
            decoded_ok = False
        if not decoded_ok:
            # accept raw id cursor (even if caller mistakenly passes an inbox id)
            cursor_draft_id = c

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_ids = {i.get("id") for i in inboxes if isinstance(i, dict) and isinstance(i.get("id"), str)}
    if not inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible inbox context found")

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []

    rows = [d for d in drafts if isinstance(d, dict) and d.get("inbox_id") in inbox_ids]
    if status is not None:
        rows = [d for d in rows if d.get("status") == status]

    def _sort_key(r):
        dt = _parse_dt(r.get(sort_by))
        if dt is None:
            return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0, dt)

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)
    total = len(rows)

    if cursor_draft_id is not None:
        pos = None
        for i, r in enumerate(rows):
            if r.get("id") == cursor_draft_id:
                pos = i
                break
        if pos is None:
            offset = total
        else:
            offset = pos + 1

    if offset < 0:
        offset = 0
    if offset > total:
        offset = total

    page = rows[offset : offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"o": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8")

    _audit("ok", None)
    return {
        "drafts": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_draft(draft_id, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_draft"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).", limit="120/min")
        if c_day >= 50000:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded (50000 requests/day).", limit="50000/day")
        return True, None

    ok, rl_err = _rate_limit_check()
    if not ok:
        _audit(429, rl_err["error"]["code"])
        return rl_err

    # IMPORTANT: datastore contains ids like am_dft_..., but tool schema pattern says ^am_dft_[0-9A-Z]+$.
    # Real backend typically validates type but may accept ids that exist even if they fail strict pattern;
    # we relax to accept any non-empty string and rely on existence.
    if not isinstance(draft_id, str) or not draft_id.strip():
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "draft_id must be a non-empty string.", draft_id=draft_id)

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []

    draft = None
    for d in drafts:
        if isinstance(d, dict) and d.get("id") == draft_id:
            draft = d
            break
    if not draft:
        _audit(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Draft not found.", draft_id=draft_id)

    # Ambient auth: no credential parameter; choose any accessible inbox. Since there is no ACL model in store,
    # treat all inboxes as accessible if referenced inbox exists.
    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_id = draft.get("inbox_id")
    if not inbox_id or not any(isinstance(i, dict) and i.get("id") == inbox_id for i in inboxes):
        _audit(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Draft inbox is not accessible or no longer exists.", inbox_id=inbox_id)

    _audit(200, None)
    return {"draft": draft}

def create_draft(inbox_id, thread_id=None, reply_to_message_id=None, from_email=None, to_emails=None, cc_emails=None, bcc_emails=None, subject=None, body_text=None, body_html=None, headers=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    reqs = _load("requests.json")
    if not isinstance(reqs, list):
        reqs = []

    def _log_and_return(payload, http_status="ok"):
        latency_ms = int((time.time() - t0) * 1000)
        reqs.append({
            "id": f"am_req_{int(time.time()*1000)}",
            "endpoint": "create_draft",
            "timestamp": now,
            "status": http_status,
            "latency_ms": latency_ms
        })
        _save("requests.json", reqs)
        return payload

    def _is_email(s):
        if not isinstance(s, str):
            return False
        s = s.strip()
        if len(s) > 320:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    def _validate_id(val, pat, name):
        if val is None:
            return None
        if not isinstance(val, str) or not re.match(pat, val):
            return _err("VALIDATION_ERROR", f"{name} format is invalid.")
        return None

    if not isinstance(inbox_id, str) or not re.match(r"^am_inbox_[0-9A-Z]+$", inbox_id):
        return _log_and_return(_err("VALIDATION_ERROR", "inbox_id format is invalid."), "error")

    e = _validate_id(thread_id, r"^am_th_[0-9A-Z]+$", "thread_id")
    if e: return _log_and_return(e, "error")
    e = _validate_id(reply_to_message_id, r"^am_msg_[0-9A-Z]+$", "reply_to_message_id")
    if e: return _log_and_return(e, "error")

    if from_email is not None and not isinstance(from_email, str):
        return _log_and_return(_err("VALIDATION_ERROR", "from_email must be a string."), "error")
    if from_email is not None and not _is_email(from_email):
        return _log_and_return(_err("VALIDATION_ERROR", "from_email must be a valid email address."), "error")

    def _validate_emails_array(arr, name):
        if arr is None:
            return None
        if not isinstance(arr, list):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings.")
        if len(arr) > 100:
            return _err("VALIDATION_ERROR", f"{name} length must be <= 100.")
        for x in arr:
            if not isinstance(x, str) or not _is_email(x):
                return _err("VALIDATION_ERROR", f"{name} must contain valid email strings.")
        return None

    e = _validate_emails_array(to_emails, "to_emails")
    if e: return _log_and_return(e, "error")
    e = _validate_emails_array(cc_emails, "cc_emails")
    if e: return _log_and_return(e, "error")
    e = _validate_emails_array(bcc_emails, "bcc_emails")
    if e: return _log_and_return(e, "error")

    if subject is not None and not isinstance(subject, str):
        return _log_and_return(_err("VALIDATION_ERROR", "subject must be a string."), "error")
    if body_text is not None and not isinstance(body_text, str):
        return _log_and_return(_err("VALIDATION_ERROR", "body_text must be a string."), "error")
    if body_html is not None and not isinstance(body_html, str):
        return _log_and_return(_err("VALIDATION_ERROR", "body_html must be a string."), "error")
    if headers is None:
        headers = {}
    if not isinstance(headers, dict):
        return _log_and_return(_err("VALIDATION_ERROR", "headers must be an object."), "error")

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox = None
    for i in inboxes:
        if isinstance(i, dict) and i.get("id") == inbox_id:
            inbox = i
            break
    if not inbox:
        return _log_and_return(_err("NOT_FOUND", "Inbox not found.", inbox_id=inbox_id), "error")

    # FK validations: thread_id and reply_to_message_id must belong to same inbox if provided
    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []
    if thread_id is not None:
        th = None
        for t in threads:
            if isinstance(t, dict) and t.get("id") == thread_id:
                th = t
                break
        if not th:
            return _log_and_return(_err("NOT_FOUND", "Thread not found.", thread_id=thread_id), "error")
        if th.get("inbox_id") != inbox_id:
            return _log_and_return(_err("UNAUTHORIZED", "Thread does not belong to this inbox.", thread_id=thread_id, inbox_id=inbox_id), "error")

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []
    if reply_to_message_id is not None:
        msg = None
        for m in messages:
            if isinstance(m, dict) and m.get("id") == reply_to_message_id:
                msg = m
                break
        if not msg:
            return _log_and_return(_err("NOT_FOUND", "Reply-to message not found.", reply_to_message_id=reply_to_message_id), "error")
        if msg.get("inbox_id") != inbox_id:
            return _log_and_return(_err("UNAUTHORIZED", "Reply-to message does not belong to this inbox.", reply_to_message_id=reply_to_message_id, inbox_id=inbox_id), "error")
        # If both provided, ensure consistent
        if thread_id is not None and msg.get("thread_id") and msg.get("thread_id") != thread_id:
            return _log_and_return(_err("CONFLICT", "thread_id does not match reply_to_message_id thread.", thread_id=thread_id, reply_to_message_id=reply_to_message_id), "error")
        # If thread_id omitted, we can associate it to message's thread_id (if any)
        if thread_id is None and msg.get("thread_id") is not None:
            thread_id = msg.get("thread_id")

    # Default arrays to [] if omitted
    if to_emails is None: to_emails = []
    if cc_emails is None: cc_emails = []
    if bcc_emails is None: bcc_emails = []

    # Determine from_email default to inbox email if not provided
    if from_email is None:
        from_email = inbox.get("email_address")
    if not _is_email(from_email):
        return _log_and_return(_err("VALIDATION_ERROR", "from_email must be a valid email address."), "error")

    # Create time policy: allow empty body at create time; but if user provided recipients/subject/etc with missing body inconsistently, allow.
    # Still validate that if any recipient provided, they are valid; already done. No requirement of any recipients at create time.

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []

    def _new_id():
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "am_dft_" + "".join(random.choice(alphabet) for _ in range(12))

    existing_ids = {d.get("id") for d in drafts if isinstance(d, dict)}
    draft_id = _new_id()
    tries = 0
    while draft_id in existing_ids and tries < 10:
        draft_id = _new_id()
        tries += 1
    if draft_id in existing_ids:
        return _log_and_return(_err("CONFLICT", "Unable to generate unique draft id."), "error")

    draft = {
        "id": draft_id,
        "inbox_id": inbox_id,
        "thread_id": thread_id,
        "reply_to_message_id": reply_to_message_id,
        "from_email": from_email,
        "to_emails": to_emails,
        "cc_emails": cc_emails,
        "bcc_emails": bcc_emails,
        "subject": subject,
        "body_text": body_text,
        "body_html": body_html,
        "headers": headers,
        "status": "draft",
        "sent_message_id": None,
        "created_at": now,
        "updated_at": now
    }

    drafts.append(draft)
    _save("drafts.json", drafts)

    return _log_and_return({"draft": draft})

def send_draft(draft_id, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "send_draft"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = _now()
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).", limit="120/min")
        if c_day >= 50000:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded (50000 requests/day).", limit="50000/day")
        return True, None

    ok, rl_err = _rate_limit_check()
    if not ok:
        _audit(429, rl_err["error"]["code"])
        return rl_err

    # Relax strict pattern (datastore is source of truth).
    if not isinstance(draft_id, str) or not draft_id.strip():
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "draft_id must be a non-empty string.", draft_id=draft_id)

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []
    draft_idx = None
    for i, d in enumerate(drafts):
        if isinstance(d, dict) and d.get("id") == draft_id:
            draft_idx = i
            break
    if draft_idx is None:
        _audit(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Draft not found.", draft_id=draft_id)

    draft = drafts[draft_idx]

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_id = draft.get("inbox_id")
    inbox = None
    for ib in inboxes:
        if isinstance(ib, dict) and ib.get("id") == inbox_id:
            inbox = ib
            break
    if not inbox:
        _audit(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Draft inbox is not accessible or no longer exists.", inbox_id=inbox_id)

    # Sendability / lifecycle transitions
    transitions = {
        "draft": ["sending", "discarded"],
        "sending": ["sent", "error"],
        "error": ["sending", "discarded"],
        "sent": [],
        "discarded": []
    }
    cur_status = draft.get("status")
    if cur_status not in transitions:
        _audit(409, "CONFLICT")
        return _err("CONFLICT", "Draft is in an unknown status and cannot be sent.", status=cur_status)

    # Idempotency: if already sent, return as-is.
    if cur_status == "sent":
        _audit(200, None)
        return {"draft": draft}

    # If already sending, return as-is (already queued)
    if cur_status == "sending":
        _audit(200, None)
        return {"draft": draft}

    if cur_status not in ("draft", "error"):
        _audit(409, "CONFLICT")
        return _err("CONFLICT", "Draft is not in a sendable state.", status=cur_status)

    # Validate constraints before transitioning to sending
    def _is_str_list(v):
        if v is None:
            return False
        if not isinstance(v, list):
            return False
        for x in v:
            if not isinstance(x, str):
                return False
        return True

    to_emails = draft.get("to_emails") if isinstance(draft.get("to_emails"), list) else []
    cc_emails = draft.get("cc_emails") if isinstance(draft.get("cc_emails"), list) else []
    bcc_emails = draft.get("bcc_emails") if isinstance(draft.get("bcc_emails"), list) else []
    if any(not isinstance(x, str) for x in (to_emails + cc_emails + bcc_emails)):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Recipient arrays must contain only strings.", draft_id=draft_id)
    if len(to_emails) > 100 or len(cc_emails) > 100 or len(bcc_emails) > 100:
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Recipient arrays may not exceed 100 entries each.", draft_id=draft_id)
    if (len(to_emails) + len(cc_emails) + len(bcc_emails)) < 1:
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one recipient across to_emails/cc_emails/bcc_emails is required to send.", draft_id=draft_id)

    body_text = draft.get("body_text")
    body_html = draft.get("body_html")
    if (body_text is None or (isinstance(body_text, str) and body_text == "")) and (body_html is None or (isinstance(body_html, str) and body_html == "")):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of body_text or body_html must be set before transitioning to sending.", draft_id=draft_id)

    # Create outbound message corresponding to this draft
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    now_iso = _now_iso()

    # Ensure FK integrity for thread/reply_to_message_id if present
    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []
    thread_id = draft.get("thread_id")
    if thread_id is not None:
        th = None
        for t in threads:
            if isinstance(t, dict) and t.get("id") == thread_id:
                th = t
                break
        if not th:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "thread_id references a non-existent thread.", thread_id=thread_id)
        if th.get("inbox_id") != inbox_id:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "thread_id must belong to the same inbox as the draft.", thread_id=thread_id, inbox_id=inbox_id)

    reply_to_message_id = draft.get("reply_to_message_id")
    if reply_to_message_id is not None:
        parent = None
        for m in messages:
            if isinstance(m, dict) and m.get("id") == reply_to_message_id:
                parent = m
                break
        if not parent:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reply_to_message_id references a non-existent message.", reply_to_message_id=reply_to_message_id)
        if parent.get("inbox_id") != inbox_id:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "reply_to_message_id must belong to the same inbox as the draft.", reply_to_message_id=reply_to_message_id, inbox_id=inbox_id)
        # Inherit thread if missing
        if thread_id is None:
            thread_id = parent.get("thread_id")

    # Build message
    msg_id = _gen_id("am_msg_")
    outbound = {
        "id": msg_id,
        "inbox_id": inbox_id,
        "thread_id": thread_id,
        "provider_message_id": None,
        "direction": "outbound",
        "from_email": draft.get("from_email") if isinstance(draft.get("from_email"), str) else inbox.get("email_address"),
        "to_emails": to_emails,
        "cc_emails": cc_emails,
        "bcc_emails": bcc_emails,
        "reply_to_emails": [],
        "subject": draft.get("subject"),
        "body_text": body_text,
        "body_html": body_html,
        "headers": draft.get("headers") if isinstance(draft.get("headers"), dict) else {},
        "labels": ["SENT"],
        "is_read": True,
        "sent_at": None,
        "status": "queued",
        "in_reply_to_message_id": reply_to_message_id,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Constraint: outbound implies status in ('queued','sending','sent','failed','deleted')
    # Constraint: at least one body is non-null for outbound messages in status != 'failed' (satisfied)
    # Uniqueness on provider_message_id: none => ok.

    # Transition draft to sending (allowed)
    if "sending" not in transitions.get(cur_status, []):
        _audit(409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Draft status transition is not permitted.", from_status=cur_status, to_status="sending")

    # Persist: add message, set draft status, set sent_message_id
    messages.append(outbound)
    draft["status"] = "sending"
    draft["sent_message_id"] = msg_id
    draft["updated_at"] = now_iso
    drafts[draft_idx] = draft

    _save("messages.json", messages)
    _save("drafts.json", drafts)

    # Simulate immediate processing outcome deterministically: queued -> sent.
    # This keeps lifecycle consistent while still observable; if message already exists, it doesn't.
    # Perform allowed transitions: queued->sending->sent, draft: sending->sent.
    # If any required fields missing for "sent", mark failed+error.
    now_iso2 = _now_iso()
    # update message row in-place
    msg_idx = None
    for i, m in enumerate(messages):
        if isinstance(m, dict) and m.get("id") == msg_id:
            msg_idx = i
            break
    if msg_idx is not None:
        # Move to sent
        messages[msg_idx]["status"] = "sent"
        messages[msg_idx]["sent_at"] = now_iso2
        messages[msg_idx]["updated_at"] = now_iso2
        _save("messages.json", messages)

        # Draft sending->sent allowed
        draft = drafts[draft_idx]
        if "sent" in transitions.get(draft.get("status"), []):
            draft["status"] = "sent"
            draft["updated_at"] = now_iso2
            drafts[draft_idx] = draft
            _save("drafts.json", drafts)
        else:
            # If cannot transition, keep sending (shouldn't happen)
            pass
    else:
        # No success without effect: message missing after append indicates datastore corruption
        _audit(500, "NOT_FOUND")
        return _err("NOT_FOUND", "Failed to create outbound message for draft.", draft_id=draft_id)

    _audit(200, None)
    return {"draft": drafts[draft_idx]}

def update_inbox(inbox_id, display_name=None, metadata=None, status=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_inbox"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).", limit="120/min")
        if c_day >= 50000:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded (50000 requests/day).", limit="50000/day")
        return True, None

    ok, rl_err = _rate_limit_check()
    if not ok:
        _audit(429, rl_err["error"]["code"])
        return rl_err

    if not isinstance(inbox_id, str) or not inbox_id.strip():
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inbox_id must be a non-empty string.", inbox_id=inbox_id)
    if not re.match(r"^am_inbox_[0-9A-Za-z]+$", inbox_id):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "inbox_id does not match required format.", inbox_id=inbox_id)

    if display_name is None and metadata is None and status is None:
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No writable fields provided; supply display_name, metadata, and/or status.")

    if display_name is not None:
        if not isinstance(display_name, str):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "display_name must be a string.", display_name=display_name)
        if not (1 <= len(display_name) <= 200):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "display_name length must be between 1 and 200 characters.", length=len(display_name))

    if metadata is not None and not isinstance(metadata, dict):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "metadata must be an object.", metadata=metadata)

    allowed_status = {"provisioning", "active", "paused", "disabled", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of provisioning, active, paused, disabled, error.", status=status)

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []

    idx = None
    for i, ib in enumerate(inboxes):
        if isinstance(ib, dict) and ib.get("id") == inbox_id:
            idx = i
            break
    if idx is None:
        _audit(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Inbox not found.", inbox_id=inbox_id)

    inbox = inboxes[idx]

    # Lifecycle transitions
    transitions = {
        "provisioning": ["active", "error", "disabled"],
        "active": ["paused", "disabled", "error"],
        "paused": ["active", "disabled", "error"],
        "error": ["active", "disabled"],
        "disabled": []
    }

    if status is not None and status != inbox.get("status"):
        cur = inbox.get("status")
        if cur not in transitions:
            _audit(409, "CONFLICT")
            return _err("CONFLICT", "Inbox has unknown current status.", status=cur)
        if status not in transitions[cur]:
            # Vendor docs mention CONFLICT for invalid transition; use CONFLICT not INVALID_TRANSITION here.
            _audit(409, "CONFLICT")
            return _err("CONFLICT", "Inbox status transition is not permitted.", from_status=cur, to_status=status)

    changed = False
    now_iso = _now_iso()
    if display_name is not None and display_name != inbox.get("display_name"):
        inbox["display_name"] = display_name
        changed = True
    if metadata is not None and metadata != inbox.get("metadata"):
        inbox["metadata"] = metadata
        changed = True
    if status is not None and status != inbox.get("status"):
        inbox["status"] = status
        changed = True

    if not changed:
        # No success without effect
        _audit(409, "CONFLICT")
        return _err("CONFLICT", "Update had no effect (fields already set to the provided values).")

    inbox["updated_at"] = now_iso
    inboxes[idx] = inbox
    _save("inboxes.json", inboxes)

    _audit(200, None)
    return {"inbox": inbox}

def update_thread(thread_id, status, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    t0 = time.time()
    endpoint = "update_thread"

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
        )
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        per_min = 120
        per_day = 50000
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if c_day >= per_day:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        _audit("error", rl["error"]["code"])
        return rl

    if not isinstance(thread_id, str) or not thread_id.strip():
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thread_id must be a non-empty string.")
    # Relax pattern mismatch in broken code: real ids are am_th_..., not am_thread_...
    if not (re.match(r"^am_th_[0-9A-Za-z]+$", thread_id.strip()) or re.match(r"^am_thread_[0-9A-Za-z]+$", thread_id.strip())):
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thread_id format is invalid.")

    allowed_status = {"active", "archived", "deleted"}
    transitions = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}

    if not isinstance(status, str) or status not in allowed_status:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(allowed_status))

    inboxes = _load("inboxes.json")
    if not isinstance(inboxes, list):
        inboxes = []
    inbox_ids = {i.get("id") for i in inboxes if isinstance(i, dict) and isinstance(i.get("id"), str)}
    if not inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No accessible inbox context found")

    threads = _load("threads.json")
    if not isinstance(threads, list):
        threads = []

    idx = None
    thr = None
    for i, r in enumerate(threads):
        if isinstance(r, dict) and r.get("id") == thread_id:
            idx = i
            thr = r
            break
    if thr is None:
        _audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Thread not found.", thread_id=thread_id)

    if thr.get("inbox_id") not in inbox_ids:
        _audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "You do not have access to this thread.")

    cur = thr.get("status")
    if cur not in allowed_status:
        _audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Existing thread has unknown status.", status=cur)

    if status != cur and status not in transitions.get(cur, set()):
        _audit("error", "CONFLICT")
        return _err("CONFLICT", "Requested status transition is not permitted.", from_status=cur, to_status=status)

    updated = dict(thr)
    updated["status"] = status
    updated["updated_at"] = _now_iso()
    threads[idx] = updated
    _save("threads.json", threads)

    _audit("ok", None)
    return {"thread": updated}

def update_draft(draft_id, to_emails=None, cc_emails=None, bcc_emails=None, subject=None, body_text=None, body_html=None, headers=None, status=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0143000" if __import__("os").path.isdir("./environment_mix/0143000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_draft"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _audit(status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "am_req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff_min = now - datetime.timedelta(seconds=60)
        cutoff_day = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= cutoff_day:
                c_day += 1
                if ts >= cutoff_min:
                    c_min += 1
        if c_min >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min).", limit="120/min")
        if c_day >= 50000:
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded (50000 requests/day).", limit="50000/day")
        return True, None

    ok, rl_err = _rate_limit_check()
    if not ok:
        _audit(429, rl_err["error"]["code"])
        return rl_err

    if not isinstance(draft_id, str) or not draft_id.strip():
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "draft_id must be a non-empty string.", draft_id=draft_id)
    # Tool schema says am_draft_..., but datastore uses am_dft_...; relax to accept either.
    if not (re.match(r"^am_dft_[0-9A-Za-z]+$", draft_id) or re.match(r"^am_draft_[0-9A-Za-z]+$", draft_id)):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "draft_id does not match required format.", draft_id=draft_id)

    provided = any(v is not None for v in (to_emails, cc_emails, bcc_emails, subject, body_text, body_html, headers, status))
    if not provided:
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No writable fields provided.")

    def _validate_email_list(name, v):
        if v is None:
            return None
        if not isinstance(v, list):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings.", field=name)
        for x in v:
            if not isinstance(x, str):
                return _err("VALIDATION_ERROR", f"{name} must contain only strings.", field=name)
        if len(v) > 100:
            return _err("VALIDATION_ERROR", f"{name} may not exceed 100 entries.", field=name, limit=100)
        return None

    for nm, vv in (("to_emails", to_emails), ("cc_emails", cc_emails), ("bcc_emails", bcc_emails)):
        e = _validate_email_list(nm, vv)
        if e:
            _audit(400, e["error"]["code"])
            return e

    if headers is not None and not isinstance(headers, dict):
        _audit(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "headers must be an object.", headers=headers)

    allowed_status = {"draft", "sending", "sent", "discarded", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of draft, sending, sent, discarded, error.", status=status)

    drafts = _load("drafts.json")
    if not isinstance(drafts, list):
        drafts = []
    idx = None
    for i, d in enumerate(drafts):
        if isinstance(d, dict) and d.get("id") == draft_id:
            idx = i
            break
    if idx is None:
        _audit(404, "NOT_FOUND")
        return _err("NOT_FOUND", "Draft not found.", draft_id=draft_id)

    draft = drafts[idx]

    # Enforce writable states: can update while draft or error (and possibly sending in some systems, but rule says writable state)
    writable_statuses = {"draft", "error"}
    if draft.get("status") not in writable_statuses:
        _audit(409, "CONFLICT")
        return _err("CONFLICT", "Draft is not in a writable status.", status=draft.get("status"))

    transitions = {
        "draft": ["sending", "discarded"],
        "sending": ["sent", "error"],
        "error": ["sending", "discarded"],
        "sent": [],
        "discarded": []
    }

    if status is not None and status != draft.get("status"):
        cur = draft.get("status")
        if status not in transitions.get(cur, []):
            _audit(409, "CONFLICT")
            return _err("CONFLICT", "Draft status transition is not permitted.", from_status=cur, to_status=status)

        # If transitioning to sending, enforce body present (business rule)
        if status == "sending":
            bt = body_text if body_text is not None else draft.get("body_text")
            bh = body_html if body_html is not None else draft.get("body_html")
            if (bt is None or (isinstance(bt, str) and bt == "")) and (bh is None or (isinstance(bh, str) and bh == "")):
                _audit(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "At least one of body_text or body_html must be set before transitioning to sending.")

        # If transitioning to sent, enforce sent_message_id present (business rule)
        if status == "sent" and not draft.get("sent_message_id"):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cannot set status='sent' unless sent_message_id is set.")

    changed = False
    if to_emails is not None and to_emails != draft.get("to_emails"):
        draft["to_emails"] = to_emails
        changed = True
    if cc_emails is not None and cc_emails != draft.get("cc_emails"):
        draft["cc_emails"] = cc_emails
        changed = True
    if bcc_emails is not None and bcc_emails != draft.get("bcc_emails"):
        draft["bcc_emails"] = bcc_emails
        changed = True
    if subject is not None and subject != draft.get("subject"):
        if not isinstance(subject, str):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "subject must be a string.", subject=subject)
        draft["subject"] = subject
        changed = True
    if body_text is not None and body_text != draft.get("body_text"):
        if not isinstance(body_text, str):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body_text must be a string.", body_text=body_text)
        draft["body_text"] = body_text
        changed = True
    if body_html is not None and body_html != draft.get("body_html"):
        if not isinstance(body_html, str):
            _audit(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body_html must be a string.", body_html=body_html)
        draft["body_html"] = body_html
        changed = True
    if headers is not None and headers != draft.get("headers"):
        draft["headers"] = headers
        changed = True
    if status is not None and status != draft.get("status"):
        draft["status"] = status
        changed = True

    if not changed:
        _audit(409, "CONFLICT")
        return _err("CONFLICT", "Update had no effect (fields already set to the provided values).")

    draft["updated_at"] = _now_iso()
    drafts[idx] = draft
    _save("drafts.json", drafts)

    _audit(200, None)
    return {"draft": draft}
